INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Betroffenenrechte > Recht auf Datenübertragbarkeit
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gewährt Art. 20 DSGVO Betroffenen das Recht, ihre personenbezogenen Daten in einem strukturierten Format zu erhalten?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 20 DSGVO garantiert Datenübertragbarkeit"}, {"text": "Nein", "correct": false, "because": "Recht ist gesetzlich verankert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Recht auf Datenübertragbarkeit auch die Übermittlung der Daten an einen anderen Verantwortlichen umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 20 Abs. 2 DSGVO erlaubt direkte Übermittlung"}, {"text": "Nein", "correct": false, "because": "Übermittlung ist Teil des Rechts"}]'),
('00000000-0000-0000-0000-000000000000', 'Gilt das Recht auf Datenübertragbarkeit für alle personenbezogenen Daten, unabhängig von der Rechtsgrundlage der Verarbeitung?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Einwilligung oder Vertrag, Art. 20 Abs. 1a"}, {"text": "Ja", "correct": false, "because": "Eingeschränkt auf bestimmte Grundlagen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Unternehmen die Datenübertragbarkeit verweigern, wenn die Daten manuell erhoben wurden?', 2, '[{"text": "Nein", "correct": true, "because": "Recht gilt für automatisierte Verarbeitung, nicht Erhebungsart"}, {"text": "Ja", "correct": false, "because": "Verweigerung nur bei fehlender Automatisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Recht auf Datenübertragbarkeit gemäß Art. 20 DSGVO kostenpflichtig für Betroffene?', 2, '[{"text": "Nein", "correct": true, "because": "Art. 12 Abs. 5 DSGVO schreibt Kostenfreiheit vor"}, {"text": "Ja", "correct": false, "because": "Kostenfreiheit ist Standard"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was erlaubt das Recht auf Datenübertragbarkeit gemäß Art. 20 DSGVO Betroffenen?', 2, '[{"text": "Daten in einem maschinenlesbaren Format erhalten", "correct": true, "because": "Art. 20 DSGVO definiert dies"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzung muss für das Recht auf Datenübertragbarkeit erfüllt sein?', 3, '[{"text": "Daten wurden automatisiert verarbeitet", "correct": true, "because": "Art. 20 Abs. 1 beschränkt es auf automatisierte Verarbeitung"}, {"text": "Daten wurden manuell erhoben", "correct": false, "because": "Nicht zutreffend"}, {"text": "Daten sind öffentlich zugänglich", "correct": false, "because": "Keine Voraussetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frist haben Unternehmen, um ein Datenübertragbarkeitsverlangen zu erfüllen?', 2, '[{"text": "Einen Monat", "correct": true, "because": "Art. 12 Abs. 3 DSGVO setzt eine Monatsfrist"}, {"text": "Drei Monate", "correct": false, "because": "Zu lang"}, {"text": "Keine Frist", "correct": false, "because": "Frist ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format müssen Unternehmen gemäß Art. 20 DSGVO für die Datenübertragbarkeit bereitstellen?', 2, '[{"text": "Strukturiertes, maschinenlesbares Format", "correct": true, "because": "Art. 20 Abs. 1 verlangt dies"}, {"text": "Papierformat", "correct": false, "because": "Nicht maschinenlesbar"}, {"text": "Unstrukturiertes Format", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei Nichtbeachtung des Rechts auf Datenübertragbarkeit?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen DSGVO strafbar"}, {"text": "Systemstilllegung", "correct": false, "because": "Keine Standardstrafe"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Indirekt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Rechte umfasst das Recht auf Datenübertragbarkeit nach Art. 20 DSGVO?', 4, '[{"text": "Daten in maschinenlesbarem Format erhalten", "correct": true, "because": "Art. 20 Abs. 1"}, {"text": "Direkte Übermittlung an anderen Verantwortlichen", "correct": true, "because": "Art. 20 Abs. 2"}, {"text": "Daten von automatisierten Verarbeitungen", "correct": true, "because": "Art. 20 Abs. 1"}, {"text": "Datenlöschung", "correct": false, "because": "Anderes Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen müssen für das Recht auf Datenübertragbarkeit erfüllt sein?', 3, '[{"text": "Verarbeitung basiert auf Einwilligung", "correct": true, "because": "Art. 20 Abs. 1a"}, {"text": "Verarbeitung basiert auf Vertrag", "correct": true, "because": "Art. 20 Abs. 1a"}, {"text": "Automatisierte Verarbeitung", "correct": true, "because": "Art. 20 Abs. 1"}, {"text": "Manuelle Verarbeitung", "correct": false, "because": "Ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten können gemäß Art. 20 DSGVO übertragen werden?', 4, '[{"text": "Daten, die der Betroffene bereitgestellt hat", "correct": true, "because": "Art. 20 Abs. 1"}, {"text": "Daten aus automatisierten Prozessen", "correct": true, "because": "Art. 20 Abs. 1"}, {"text": "Daten basierend auf Einwilligung", "correct": true, "because": "Art. 20 Abs. 1a"}, {"text": "Daten aus gesetzlichen Verpflichtungen", "correct": false, "because": "Ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen das Recht auf Datenübertragbarkeit haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen DSGVO strafbar"}, {"text": "Schadensersatzansprüche", "correct": true, "because": "Betroffene können klagen"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kundenvertrauen schwindet"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Softwareplanung unterstützen das Recht auf Datenübertragbarkeit?', 3, '[{"text": "Daten in maschinenlesbarem Format speichern", "correct": true, "because": "Erleichtert Übertragung"}, {"text": "Exportfunktionen implementieren", "correct": true, "because": "Ermöglicht Datenübergabe"}, {"text": "Dokumentation der Verarbeitung", "correct": true, "because": "Nachweis erforderlich"}, {"text": "Unstrukturierte Datenspeicherung", "correct": false, "because": "Widerspricht Anforderung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Recht auf Datenübertragbarkeit erfordert ein maschinenlesbares Format. b) Es gilt für alle Verarbeitungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Format ja, nur bestimmte Verarbeitungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Betroffene können Daten an Dritte übermitteln lassen. b) Es ist kostenpflichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Übermittlung ja, kostenfrei nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Recht auf Datenübertragbarkeit gilt bei automatisierten Verarbeitungen. b) Unternehmen haben drei Monate Zeit zur Erfüllung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Automatisiert ja, Frist ein Monat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Verstöße gegen das Recht auf Datenübertragbarkeit können Bußgelder nach sich ziehen. b) Es gilt nur bei Einwilligung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, auch bei Vertrag"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Exportfunktionen in Software unterstützen die Datenübertragbarkeit. b) Es umfasst alle Daten unabhängig vom Zweck.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Export ja, nur bestimmte Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

